def safe_target(root: Path, relative: str) -> Path:
    part = PurePosixPath(relative)
    if part.is_absolute() or not part.parts or any(p in (".", "..") for p in part.parts):
        raise ValueError(f"Unsafe release path: {relative!r}")
    if "\\" in relative or ":" in relative or str(part) != relative:
        raise ValueError(f"Non-portable release path: {relative!r}")
    target = root.joinpath(*part.parts).resolve()
    if not target.is_relative_to(root) or target == root:
        raise ValueError(f"Release path escapes project root: {relative!r}")
    return target


def apply(root: Path, dry_run: bool = False) -> tuple[str, int]:
    root = root.resolve(strict=True)
    gradle = safe_target(root, "app/build.gradle.kts").read_text(encoding="utf-8-sig")
    application_ids = re.findall(r'(?m)^\s*applicationId\s*=\s*"([^"\r\n]+)"', gradle)
    if len(application_ids) != 1 or application_ids[0] not in (
        "io.mirr.plexplay", "io.mirr.plexplay.universal"
    ):
        raise ValueError("Expected one supported Plex Play applicationId in app/build.gradle.kts")
    variant = "universal" if application_ids[0].endswith(".universal") else "main"
    compressed = base64.b64decode(PAYLOAD_B64, validate=True)
    if hashlib.sha256(compressed).hexdigest() != PAYLOAD_SHA256:
        raise ValueError("Subtitle release payload checksum mismatch")
    payload = json.loads(gzip.decompress(compressed).decode("utf-8"))
    if payload.get("schema") != 1 or set(payload.get("variants", {})) != set(ALLOWED_FILES):
        raise ValueError("Unexpected subtitle release payload schema")
    files = payload["variants"][variant]
    if not isinstance(files, dict) or set(files) != set(ALLOWED_FILES[variant]):
        raise ValueError("Subtitle release payload does not match the file allowlist")

    # Validate every path and content before making the first filesystem change.
    writes = []
    for relative in ALLOWED_FILES[variant]:
        entry = files[relative]
        if not isinstance(entry, dict) or set(entry) != {"text", "sha256"}:
            raise ValueError(f"Invalid release file entry: {relative}")
        data = entry["text"].encode("utf-8")
        if hashlib.sha256(data).hexdigest() != entry["sha256"]:
            raise ValueError(f"Release file checksum mismatch: {relative}")
        target = safe_target(root, relative)
        if not target.is_file() or target.read_bytes() != data:
            writes.append((target, data))

    if not dry_run:
        for target, data in writes:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(data)
    print(f"Plezy subtitles: {variant}; {len(files)} files verified; "
          f"{len(writes)} files {'would change' if dry_run else 'updated'}")
    return variant, len(writes)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", type=Path, nargs="?", default=Path.cwd())
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args()
    apply(args.root, args.dry_run)
